create table support_access_sessions(id uuid primary key default gen_random_uuid(),requester_id uuid not null references internal_users(id),organisation_id uuid not null references organisations(id) on delete restrict,customer_account_id uuid not null references customer_accounts(id) on delete restrict,case_reference text not null,reason text not null check(length(trim(reason))>0),requested_scope text not null check(requested_scope in('read_only','troubleshooting','elevated')),approved_scope text not null check(approved_scope in('read_only','troubleshooting','elevated')),status text not null check(status in('active','ended','revoked','expired')),started_at timestamptz not null default now(),expires_at timestamptz not null,ended_at timestamptz,ended_by uuid references internal_users(id),check(expires_at>started_at),check(status='active' or ended_at is not null));
create index idx_support_access_active on support_access_sessions(requester_id,organisation_id,expires_at) where status='active';
create table support_access_events(id uuid primary key default gen_random_uuid(),support_session_id uuid references support_access_sessions(id) on delete restrict,actor_id uuid not null references internal_users(id),organisation_id uuid not null references organisations(id) on delete restrict,action text not null,resource_classification text not null,resource_identifier text not null,outcome text not null check(outcome in('allowed','denied')),reason text,request_id text not null,occurred_at timestamptz not null default now());
alter table support_access_sessions enable row level security;alter table support_access_events enable row level security;
grant select,insert,update on support_access_sessions to authenticated;grant select,insert on support_access_events to authenticated;
create policy support_sessions_select on support_access_sessions for select using(is_active_internal_user());create policy support_sessions_insert on support_access_sessions for insert with check(requester_id=auth.uid() and internal_has_role(array['super_admin','operations','customer_success','support']::internal_role[]));create policy support_sessions_update on support_access_sessions for update using(requester_id=auth.uid() or internal_has_role(array['super_admin','operations']::internal_role[])) with check(status<>'active');
create policy support_events_select on support_access_events for select using(internal_has_role(array['super_admin','operations','support']::internal_role[]));create policy support_events_insert on support_access_events for insert with check(actor_id=auth.uid() and is_active_internal_user());
